(()=>{const out={},ns='http://www.w3.org/2000/svg',svg=document.createElementNS(ns,'svg');document.body.append(svg);for(const family of ['"Segoe UI Emoji"','"Segoe UI Emoji", Tahoma','Tahoma','Arial'])for(const text of ['e\u0301','\u00e9','a\u0308','\u00e4','n\u0303','\u00f1','e\u0301x','\u00e9x']){const n=document.createElementNS(ns,'text');n.style.fontFamily=family;n.style.fontSize='16px';n.textContent=text;svg.append(n);out[family+'|'+text]=n.getComputedTextLength();n.remove()}svg.remove();return out})()